namespace OpticalConstructor.Controls

/// What a static command does: its tooltip and its UI Automation help text (spec 0051 `.manual/007` 1.5).
type CommandHelp =
    | CommandHelp of string

    member this.value : string = let (CommandHelp text) = this in text

/// What every static command does, in one place: its tooltip and its UI Automation help text (spec 0051 `.manual/007`
/// 1.5). A command's key is its id up to its first `_`, so a repeated command (`ExperimentView_<n>`) shares one text.
/// `AutomationContractTests` fails for a command shown without one.
[<AutoOpen>]
module ConstructorUiIdHelp =

    type ConstructorUiId with

        /// The command's help, the MS Word ScreenTip's sentence: what it does and what it changes; none for an id that
        /// is not a static command (a text, a list, a dynamic button whose caption is its tooltip).
        member this.helpOpt : CommandHelp option =
            let key =
                match this.value.IndexOf '_' with
                | index when index > 0 -> this.value.Substring(0, index)
                | _ -> this.value
            let text =
                match key with
                // The rotation bar and the table's tabs.
                | "RotationR1MinusButton" | "TeRotateR1MinusButton" | "ElemRotateR1MinusButton" | "RotateR1MinusButton" -> "Turns the selected element (or the table) by one step back about its first axis, R1."
                | "RotationR1PlusButton" | "TeRotateR1PlusButton" | "ElemRotateR1PlusButton" | "RotateR1PlusButton" -> "Turns the selected element (or the table) by one step forward about its first axis, R1."
                | "RotationR2MinusButton" | "TeRotateR2MinusButton" | "ElemRotateR2MinusButton" | "RotateR2MinusButton" -> "Tilts the selected element by one step back about its second axis, R2: the angle of incidence."
                | "RotationR2PlusButton" | "TeRotateR2PlusButton" | "ElemRotateR2PlusButton" | "RotateR2PlusButton" -> "Tilts the selected element by one step forward about its second axis, R2: the angle of incidence."
                | "RotationR3MinusButton" | "TeRotateR3MinusButton" | "ElemRotateR3MinusButton" | "RotateR3MinusButton" -> "Spins the selected element by one step back about its third axis, R3, its normal."
                | "RotationR3PlusButton" | "TeRotateR3PlusButton" | "ElemRotateR3PlusButton" | "RotateR3PlusButton" -> "Spins the selected element by one step forward about its third axis, R3, its normal."
                | "RotationLockR1Button" -> "Locks or unlocks turning the selected element about R1."
                | "RotationLockR2Button" -> "Locks or unlocks tilting the selected element about R2."
                | "RotationLockR3Button" | "TeUnlockR3Button" | "ElemUnlockR3Button" -> "Locks or unlocks spinning the selected element about R3."
                | "RotationResetButton" | "TeResetButton" | "ElemResetButton" -> "Puts the selected element back at its starting angles; asks first."
                | "RotationResetAllButton" -> "Puts every element of the table back at its starting angles; asks first."
                | "ResetViewButton" -> "Puts the view of the table back: no turn, no pan, no zoom. The setup is not changed."
                | "RotateAboutIncidentFaceCheck" -> "Turns every element about the middle of the face the light enters, instead of about its centre, so the ray keeps meeting it there."
                | "PaletteRemoveSelectedButton" -> "Removes the selected element from the table."
                | "RayPositionMinusButton" -> "Moves the selected element one step back along its ray."
                | "RayPositionPlusButton" -> "Moves the selected element one step forward along its ray."
                | "RayPositionResetButton" -> "Puts the selected element back at its starting place on its ray."
                | "TablePositionXMinusButton" -> "Moves the light source one step back along the table's x; every element moves with it."
