                | "TablePositionYMinusButton" -> "Moves the light source one step back along the table's y."
                | "TablePositionYPlusButton" -> "Moves the light source one step forward along the table's y."
                | "TablePositionZMinusButton" -> "Lowers the light source by one step."
                | "TablePositionZPlusButton" -> "Raises the light source by one step."
                | "TablePositionXLockButton" | "TablePositionYLockButton" | "TablePositionZLockButton" -> "Locks or unlocks moving the light source along this axis."
                | "TablePositionResetButton" -> "Puts the light source back at its starting place."
                | "RendererSwapButton" -> "Swaps the two drawing presets of the table's elements."
                | "RibbonTab" -> "Shows this tab's controls for the table."
                // The experiment editor.
